TLM.f("Sancti/10-DU",{"officium":"In festo Domino nostro Jesu Christi Regis","rule":["9 lectiones","Gloria","Credo","Prefatio=Regis","Festum Domini"],"sections":{"Introitus":[{"k":"ref","la":"Apoc 5:12; 1:6"},{"k":"text","la":"Dignus est Agnus, qui occísus est, accípere virtútem, et divinitátem, et sapiéntiam, et fortitúdinem, et honórem. Ipsi glória et impérium in sǽcula sæculórum."},{"k":"ref","la":"Ps 71:1"},{"k":"text","la":"Deus, judícium tuum Regi da: et justítiam tuam Fílio Regis."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dignus est Agnus, qui occísus est, accípere virtútem, et divinitátem, et sapiéntiam, et fortitúdinem, et honórem. Ipsi glória et impérium in sǽcula sæculórum."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui in dilécto Fílio tuo, universórum Rege, ómnia instauráre voluísti: concéde propítius; ut cunctæ famíliæ géntium, peccáti vúlnere disgregátæ, ejus suavissímo subdántur império:"},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Colossénses."},{"k":"ref","la":"Col 1:12-20"},{"k":"text","la":"Fratres: Grátias ágimus Deo Patri, qui dignos nos fecit in partem sortis sanctórum in lúmine: qui erípuit nos de potestáte tenebrárum, et tránstulit in regnum Fílii dilectiónis suæ, in quo habémus redemptiónem per sánguinem ejus, remissiónem peccatórum: qui est imágo Dei invisíbilis, primogénitus omnis creatúra: quóniam in ipso cóndita sunt univérsa in cœlis et in terra, visibília et invisibília, sive Throni, sive Dominatiónes, sive Principátus, sive Potestátes: ómnia per ipsum, et in ipso creáta sunt: et ipse est ante omnes, et ómnia in ipso constant. Et ipse est caput córporis Ecclésiæ, qui est princípium, primogénitus ex mórtuis: ut sit in ómnibus ipse primátum tenens; quia in ipso complácuit omnem plenitúdinem inhabitáre; et per eum reconciliáre ómnia in ipsum, pacíficans per sánguinem crucis ejus, sive quæ in terris, sive quæ in cœlis sunt, in Christo Jesu Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 71:8; 78:11"},{"k":"text","la":"Dominábitur a mari usque ad mare, et a flúmine usque ad términos orbis terrárum."},{"k":"text","la":"Et adorábunt eum omnes reges terræ: omnes gentes sérvient ei. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Dan 7:14"},{"k":"text","la":"Potéstas ejus, potéstas ætérna, quæ non auferétur: et regnum ejus, quod non corrumpétur. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Dan 7:14"},{"k":"text","la":"Potéstas ejus, potéstas ætérna, quæ non auferétur: et regnum ejus, quod non corrumpétur. Allelúja."},{"k":"ref","la":"Apoc 19:16"},{"k":"text","la":"Habet in vestiménto et in fémore suo scriptum: Rex regum, et Dóminus dominántium. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 88:27-28; 88:30"},{"k":"text","la":"Ipse invocábit me; Pater meus es tu: Deus meus, et suscéptor salútis meæ."},{"k":"text","la":"Et ego primogénitum ponam illum: excélsum præ régibus terræ.","mark":"V"},{"k":"text","la":"Et ponam in sǽculum sǽculi semen ejus: et thronum ejus sicut dies cœli.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem."},{"k":"ref","la":"Joann 18:33-37"},{"k":"text","la":"In illo témpore: Dixit Pilátus ad Jesum: Tu es Rex Judæórum? Respóndit Jesus: A temetípso hoc dicis, an álii dixérunt tibi de me? Respóndit Pilátus: Numquid ego Judǽus sum? Gens tua et pontífices tradidérunt te mihi: quid fecísti? Respóndit Jesus: Regnum meum non est de hoc mundo. Si ex hoc mundo esset regnum meum, minístri mei útique decertárent, ut non tráderer Judǽis: nunc autem regnum meum non est hinc. Dixit ítaque ei Pilátus: Ergo Rex es tu? Respóndit Jesus: Tu dicis, quia Rex sum ego. Ego in hoc natus sum et ad hoc veni in mundum, ut testimónium perhíbeam veritáti: omnis, qui est ex veritáte, audit vocem meam."}],"Offertorium":[{"k":"ref","la":"Ps 2:8"},{"k":"text","la":"Póstula a me, et dabo tibi gentes hereditátem tuam, et possessiónem tuam términos terræ."}],"Secreta":[{"k":"text","la":"Hóstiam tibi, Dómine, humánæ reconciliatiónis offérimus: præsta, quǽsumus; ut, quem sacrifíciis præséntibus immolámus, ipse cunctis géntibus unitátis et pacis dona concédat, Jesus Christus Fílius tuus, Dóminus noster:"},{"k":"macro","name":"Qui tecum"}],"Communio":[{"k":"ref","la":"Ps 28:10; 28:11"},{"k":"text","la":"Sedébit Dóminus Rex in ætérnum: Dóminus benedícet pópulo suo in pace."}],"Postcommunio":[{"k":"text","la":"Immortalitátis alimóniam consecúti, quǽsumus, Dómine: ut, qui sub Christi Regis vexíllis militáre gloriámur, cum ipso, in cœlésti sede, júgiter regnáre possímus:"},{"k":"macro","name":"Qui tecum"}]},"hr":{"dd91145e665f19c7":{"t":"Otk 5, 12; 1, 6, Ps 71, 1\n(Otk 5, 12; 1, 6) Dostojno je Janje, koje je zaklano, da primi moć i božanstvo i mudrost i snagu i čast. Njemu slava i kraljevstvo u vijeke vjekova. (Ps 71, 1) Bože, daj svoje suđenje kralju, i svoju pravdu sinu kraljevu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Otk 5, 12; 1, 6) Dostojno je Janje, koje je zaklano, da primi moć i božanstvo i mudrost i snagu i čast. Njemu slava i kraljevstvo u vijeke vjekova."},"23ccd81667d7dc54":{"t":"<i>Pomolimo se</i>.\nSvemogući vjekovječni Bože, koji si po svojem ljubljenom Sinu, Kralju vasione, htio sve obnoviti, dopusti milostivo, da se sve obitelji naroda, razjedinjene ranom grijeha, podlože njegovoj preblagoj vlasti:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"e05e1c06cf0017dc":{"t":"Kol 1, 12-20\nČitanje Poslanice bl. Pavla apostola Kološanima. Braćo, zahvaljujemo Bogu Ocu, koji nas učini dostojnim subaštinicima svetaca u svjetlosti. On nas izbavi od vlasti tame i prenese u kraljevstvo svojega ljubljenog Sina, u kojem po njegovoj krvi imamo otkup i oprost grijeha. On je slika nevidljivog Boga, rođen prije svih stvorova, jer je u njemu stvoreno sve, što je na nebu i na zemlji, vidljivo i nevidljivo, prijestolja, gospodstva, poglavarstva, vlasti. Sve je stvoreno po njemu i za njega. On je prije svega i sve postoji po njemu. On je glava tijela, Crkve; on je početak, prvenac uskrsnuća od mrtvih, da u svemu bude prvi. Svidjelo se (Bogu), da u njemu stanuje sva punina i da njegovim posredovanjem, uspostavivši mir krvlju njegova križa, pomiri sa sobom sve, što je na zemlji ili na nebu, u Kristu Isusu našem Gospodinu."},"4ce46b7a570d83eb":{"t":"Ps 71, 8 i 11\nVladat će od mora do mora, i od rijeke do kraja zemlje. I njemu će se klanjati svi zemaljski kraljevi, svi će mu narodi služiti.\n\nDn 7, 14\n<i>Aleluja</i>, <i>aleluja</i>.\nNjegova je vlast vječna, i neće mu se oduzeti, i njegovo se kraljevstvo neće srušiti. <i>Aleluja</i>."},"00aeefcf19a742cb":{"t":"Iv 18, 33-37\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme: Upita Pilat Isusa: Jesi li ti kralj židovski? Isus odgovori: Govoriš li to sam od sebe ili su ti drugi to rekli za mene? Pilat odgovori: Zar sam ja Židov? Tvoj narod i svećenički poglavari predali su te meni. Što si učinio? Isus odgovori: Moje kraljevstvo nije od ovoga svijeta. Kada bi moje kraljevstvo bilo od ovoga svijeta, moji bi se sluge borili, da ne budem predan Židovima. Ali moje kraljevstvo nije odavde. Tada mu reče Pilat: Dakle, ti si kralj? Isus odgovori: Pravo kažeš, ja sam Kralj. Ja sam se rodio i došao na svijet zato, da svjedočim za istinu. Svatko, tko je od istine, sluša moj glas."},"99b782513f0a1598":{"t":"Ps 2, 8\nTraži od mene i dat ću ti narode u nasljedstvo i krajeve zemlje u posjed."},"ddf50c5e1af3ae15":{"t":"Gospodine, prinosimo ti žrtvu pomirenja ljudskog roda moleći te, da onaj, kojega ti u ovoj žrtvi prikazujemo, podijeli svim narodima darove jedinstva i mira, Isus Krist Sin tvoj, Gospodin naš:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"30f35b43f811240f":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: – koji si svoga jedinorođenoga Sina, Gospodina našega Isusa Krista, vječnog svećenika i kralja vasione, pomazao uljem radosti; da prikazavši samoga sebe na žrtveniku križa kao neokaljanu i pomirnu žrtvu, izvrši tajne ljudskog otkupljenja, i podloživši sva stvorenja svojoj vlasti preda tvojem neizmjernom veličanstvu vječno i sveopće kraljevstvo: kraljevstvo istine i života, kraljevstvo svetosti i milosti, kraljevstvo pravde, ljubavi i mira. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"8083a68cff9f7273":{"t":"Ps 28, 10 i 11\nStolovat će Gospodin Kralj u vijeke; Gospodin će blagosloviti svoj puk u miru."},"a761c1226c534f82":{"t":"<i>Pomolimo se</i>.\nPrimivši hranu neumrlosti molimo, Gospodine, da mi, koji se ponosimo, što vojujemo pod barjakom Krista Kralja, u nebeskim dvorima uzmognemo neprestano kraljevati s njime:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
